# owner: platform
from typing import Iterable, List

from rosterkit.models import Student
from rosterkit.errors import ProjectError

# ---
def contact_rows(students: Iterable[Student]) -> List[str]:
    """Text rows of name, section and email, by name."""
    roster = sorted(
        students, key=lambda item: item.display_name
    )
    if not roster:
        raise ProjectError("no students for contact sheet")
    for item in roster:
        if not item.email:
            raise ProjectError(
                f"no email for {item.display_name}"
            )
    names = [item.display_name for item in roster]
    name_wide = max(len(name) for name in names)
    sect_wide = max(len(item.section) for item in roster)
    return [
        f"{name:<{name_wide}}  "
        f"{item.section:<{sect_wide}}  {item.email}"
        for name, item in zip(names, roster)
    ]
